'use client';

import { useId, useRef, useState } from 'react';
import './verification-code-slots.css';

export interface VerificationCodeSlotsProps {
  value: string;
  onChange: (value: string) => void;
  /** Called once all slots are filled. */
  onComplete?: (code: string) => void;
  length?: number;
  label: string;
  /** Shake the slots and show this message. */
  error?: string;
  className?: string;
}

/**
 * One real input (so paste, autofill, backspace and screen readers behave
 * normally) drawn as separate slots. A highlight follows the next slot to
 * fill.
 */
export function VerificationCodeSlots({
  value,
  onChange,
  onComplete,
  length = 6,
  label,
  error,
  className = '',
}: VerificationCodeSlotsProps) {
  const input = useRef<HTMLInputElement>(null);
  const [focused, setFocused] = useState(false);
  const id = useId();
  const active = Math.min(value.length, length - 1);

  return (
    <div className={`mg-otp ${className}`} data-error={Boolean(error)}>
      <label htmlFor={id} className='mg-otp__label'>
        {label}
      </label>
      <div className='mg-otp__field'>
        <input
          ref={input}
          id={id}
          className='mg-otp__input'
          inputMode='numeric'
          autoComplete='one-time-code'
          pattern='[0-9]*'
          maxLength={length}
          value={value}
          aria-invalid={Boolean(error)}
          aria-describedby={error ? `${id}-error` : undefined}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          onChange={(event) => {
            const digits = event.target.value
              .replace(/\D/g, '')
              .slice(0, length);
            onChange(digits);
            if (digits.length === length) onComplete?.(digits);
          }}
          onSelect={(event) => {
            // Keep the caret at the end so typing always fills the next slot.
            const el = event.currentTarget;
            if (el.selectionStart !== el.value.length)
              el.setSelectionRange(el.value.length, el.value.length);
          }}
        />
        <div
          className='mg-otp__slots'
          aria-hidden='true'
          onClick={() => input.current?.focus()}
        >
          {Array.from({ length }, (_, i) => (
            <span
              key={i}
              className='mg-otp__slot'
              data-filled={i < value.length}
              data-active={focused && i === active}
            >
              {value[i] ?? ''}
            </span>
          ))}
        </div>
      </div>
      <p id={`${id}-error`} className='mg-otp__error' role='alert'>
        {error ?? ''}
      </p>
    </div>
  );
}

.mg-otp {
  display: grid;
  gap: 6px;
  color: var(--mg-text, #ffffff);
}

.mg-otp__label {
  font-weight: 700;
}

.mg-otp__field {
  position: relative;
}

/* The real input sits on top, transparent, so taps and paste reach it. */
.mg-otp__input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
  color: transparent;
  caret-color: transparent;
  font: inherit;
  letter-spacing: 2em;
  opacity: 0.01;
}

.mg-otp__slots {
  display: grid;
  grid-template-columns: repeat(6, 44px);
  gap: 8px;
}

.mg-otp__slot {
  display: grid;
  place-items: center;
  height: 52px;
  border: 2px solid var(--mg-line-strong, #474747);
  border-radius: 10px;
  background: #121212;
  font-size: 22px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  transition:
    border-color 150ms ease,
    box-shadow 150ms ease,
    transform 150ms ease;
}

.mg-otp__slot[data-filled='true'] {
  border-color: var(--mg-text, #ffffff);
}

.mg-otp__slot[data-active='true'] {
  border-color: var(--mg-accent-text, #648aff);
  box-shadow: 0 0 0 3px #303030;
  transform: translateY(-2px);
}

.mg-otp__slot[data-active='true']:empty::after {
  width: 2px;
  height: 22px;
  background: var(--mg-accent, #0047ff);
  content: '';
  animation: mg-otp-caret 1s steps(1) infinite;
}

.mg-otp[data-error='true'] .mg-otp__slots {
  animation: mg-otp-shake 320ms ease;
}

.mg-otp[data-error='true'] .mg-otp__slot {
  border-color: #ffffff;
}

.mg-otp__error {
  min-height: 1.3em;
  margin: 0;
  color: #ffffff;
  font-size: 13px;
}

@keyframes mg-otp-caret {
  50% {
    opacity: 0;
  }
}

@keyframes mg-otp-shake {
  25% {
    transform: translateX(-6px);
  }
  75% {
    transform: translateX(6px);
  }
}

@media (prefers-reduced-motion: reduce) {
  .mg-otp__slot {
    transition: none;
  }
  .mg-otp__slot[data-active='true'] {
    transform: none;
  }
  .mg-otp[data-error='true'] .mg-otp__slots,
  .mg-otp__slot[data-active='true']:empty::after {
    animation: none;
  }
}
